const expansionDishIds = new Set(dishes.map(d => d.id));
const expansionDishNames = new Set(dishes.map(d => String(d.name||'').toLocaleLowerCase('pl').replace(/\s+/g,' ').trim()));
for (const d of expansionDishes) {
  if (expansionDishIds.has(d.id)) throw new Error(`Duplicate dish id in expansion: ${d.id}`);
  const k = String(d.name||'').toLocaleLowerCase('pl').replace(/\s+/g,' ').trim();
  if (expansionDishNames.has(k)) throw new Error(`Duplicate dish name in expansion: ${d.name}`);
  expansionDishIds.add(d.id); expansionDishNames.add(k);
  dishes.push(d);
}
dishCatalogInfo.count = dishes.length;
dishCatalogInfo.homemade = dishes.filter(d=>d.type==='domowe').length;
dishCatalogInfo.fastFood = dishes.filter(d=>d.type==='fast-food').length;
dishCatalogInfo.categoryCounts = Object.fromEntries([...new Set(dishes.map(d=>d.category))].sort().map(c=>[c,dishes.filter(d=>d.category===c).length]));
dishCatalogInfo.expansion = {added: expansionDishes.length, sourceKind: 'recipe-calculated-reference', confidence: 'low; explicit recipe weights, approximate ingredient profiles', duplicatesRejected: 114, date: '2026-11-23'};
dishCatalogInfo.version = '2026-11-23.3';
dishCatalogInfo.auditDate = '2026-11-23';
dishCatalogInfo.note += ' Rozbudowa 2026-11-23: 1 595 nowych receptur; gramatury porcji i składników są jawne, lecz makroskładniki składników oparto na orientacyjnych profilach. Nie są to wartości oficjalne restauracji ani bezpośredni eksport rekordów FDC; poziom pewności niski.';
